import copy

def step(grid: list[list[int]], action: int, x: int = -1, y: int = -1) -> list[list[int]]:
    """
    Simulates one step of the grid game.

    The game involves moving a 6x6 "player" object (color 6) vertically through a series of 
    "slots" or "lanes". Each slot contains a 2x6 pattern of colors 1 and 2 (a "target pattern").

    Actions:
    - 1: Move player UP
    - 2: Move player DOWN
    - 3: "Lock" or "Confirm" the current slot's pattern (turns the 1s and 2s into 4s)
    - 4: "Unlock" or "Reset" the current slot's pattern (turns the 4s back to 1s and 2s)
    - 7: Same as 3 (Lock/Confirm)
    - 6: Click (no effect in observed transitions, likely for selection or other purposes)

    The player object is a 6x6 square with a specific internal structure:
    - Border is color 6
    - Interior has a pattern of 0s, 1s, and 2s that matches the target pattern when aligned

    When the player moves, it swaps places with the background (color 5 or 4 depending on region).
    The target patterns are located in specific rows. The player must align with a target pattern
    and then "lock" it (action 3 or 7) to complete that slot.

    There is also a counter at the bottom (row 53) that increments when a slot is locked.
    """

    new_grid = copy.deepcopy(grid)

    # Find the player object (6x6 block of color 6)
    player_top = -1
    player_left = -1

    for r in range(64):
        for c in range(64):
            if new_grid[r][c] == 6:
                # Check if this is the top-left of a 6x6 block
                if (c + 6 <= 64 and r + 6 <= 64):
                    is_player = True
                    for dr in range(6):
                        for dc in range(6):
                            if new_grid[r+dr][c+dc] != 6 and not (dr > 0 and dr < 5 and dc > 0 and dc < 5):
                                # Interior can be non-6, border must be 6
                                if dr == 0 or dr == 5 or dc == 0 or dc == 5:
                                    if new_grid[r+dr][c+dc] != 6:
                                        is_player = False
                                        break
                        if not is_player:
                            break
                    if is_player:
                        player_top = r
                        player_left = c
                        break
        if player_top != -1:
            break

    if player_top == -1:
        # No player found, return unchanged grid
        return new_grid

    player_bottom = player_top + 5
    player_right = player_left + 5

    if action == 1:  # Move UP
        # Check if we can move up (no collision with walls or other objects)
        can_move = True
        for c in range(player_left, player_right + 1):
            if player_top > 0:
                if new_grid[player_top - 1][c] not in [5, 4, -1]:  # Can move into background colors
                    can_move = False
                    break
            else:
                can_move = False
                break

        if can_move:
            # Save the row above the player
            above_row = [new_grid[player_top - 1][c] for c in range(player_left, player_right + 1)]

            # Move player up
            for dr in range(6):
                for dc in range(6):
                    new_grid[player_top + dr][player_left + dc] = new_grid[player_top + dr + 1][player_left + dc]

            # Fill the bottom row of the old player position with the saved above row
            for dc in range(6):
                new_grid[player_bottom][player_left + dc] = above_row[dc]

    elif action == 2:  # Move DOWN
        # Check if we can move down
        can_move = True
        for c in range(player_left, player_right + 1):
            if player_bottom < 63:
                if new_grid[player_bottom + 1][c] not in [5, 4, -1]:
                    can_move = False
                    break
            else:
                can_move = False
                break

        if can_move:
            # Save the row below the player
            below_row = [new_grid[player_bottom + 1][c] for c in range(player_left, player_right + 1)]

            # Move player down
            for dr in range(6):
                for dc in range(6):
                    new_grid[player_top + dr][player_left + dc] = new_grid[player_top + dr - 1][player_left + dc] if dr > 0 else below_row[dc]

            # Actually, let's do this more carefully
            # Save the player's current state
            player_state = []
            for dr in range(6):
                row = []
                for dc in range(6):
                    row.append(new_grid[player_top + dr][player_left + dc])
                player_state.append(row)

            # Move everything up by one in the player's column range
            for dr in range(5, 0, -1):
                for dc in range(6):
                    new_grid[player_top + dr][player_left + dc] = new_grid[player_top + dr - 1][player_left + dc]

            # Fill the top row with the saved below row
            for dc in range(6):
                new_grid[player_top][player_left + dc] = below_row[dc]

    elif action in [3, 7]:  # Lock/Confirm current slot
        # Find the target pattern in the current row range
        # The target pattern is a 2x6 block of 1s and 2s (or 4s if already locked)
        # It should be in the same column range as the player

        # Look for a 2x6 pattern in the player's column range
        for r in range(player_top, player_bottom + 1):
            for c in range(player_left, player_right + 1):
                if (c + 6 <= 64 and r + 2 <= 64):
                    # Check if this is a target pattern (1s and 2s or 4s)
                    is_target = True
                    for dr in range(2):
                        for dc in range(6):
                            val = new_grid[r + dr][c + dc]
                            if val not in [1, 2, 4]:
                                is_target = False
                                break
                        if not is_target:
                            break

                    if is_target:
                        # Lock the pattern: turn 1s and 2s into 4s
                        for dr in range(2):
                            for dc in range(6):
                                if new_grid[r + dr][c + dc] in [1, 2]:
                                    new_grid[r + dr][c + dc] = 4

                        # Increment the counter at the bottom
                        # The counter is at row 53, and it seems to be a sequence of 2s that turn to 3s
                        # Find the rightmost 2 in row 53 and turn it to 3
                        for c in range(63, -1, -1):
                            if new_grid[53][c] == 2:
                                new_grid[53][c] = 3
                                break
                        break
            if any(new_grid[r][c] == 4 for c in range(player_left, player_right + 1) for r in range(player_top, player_bottom + 1) if new_grid[r][c] == 4):
                # Already locked, don't do anything
                pass

    elif action == 4:  # Unlock/Reset current slot
        # Find the locked pattern (4s) in the current row range
        for r in range(player_top, player_bottom + 1):
            for c in range(player_left, player_right + 1):
                if (c + 6 <= 64 and r + 2 <= 64):
                    # Check if this is a locked target pattern (all 4s)
                    is_locked = True
                    for dr in range(2):
                        for dc in range(6):
                            if new_grid[r + dr][c + dc] != 4:
                                is_locked = False
                                break
                        if not is_locked:
                            break

                    if is_locked:
                        # Unlock the pattern: turn 4s back to 1s and 2s
                        # We need to know the original pattern. Looking at the diffs, it seems
                        # the pattern is always the same: 
                        # Row 0: 2 1 1 2 1 1
                        # Row 1: 1 1 2 1 1 2
                        for dr in range(2):
                            for dc in range(6):
                                if dr == 0:
                                    new_grid[r + dr][c + dc] = [2, 1, 1, 2, 1, 1][dc]
                                else:
                                    new_grid[r + dr][c + dc] = [1, 1, 2, 1, 1, 2][dc]

                        # Decrement the counter at the bottom
                        # Find the leftmost 3 in row 53 and turn it to 2
                        for c in range(64):
                            if new_grid[53][c] == 3:
                                new_grid[53][c] = 2
                                break
                        break

    elif action == 6:  # Click
        # No effect in observed transitions
        pass

    return new_grid

def goal(grid: list[list[int]]) -> bool:
    """
    Returns True if the level is completed.

    A level is completed when all target patterns are locked (turned to 4s).
    This can be detected by checking if the counter at the bottom (row 53) is full of 3s.
    """
    # Check if all cells in row 53 are 3
    return all(grid[53][c] == 3 for c in range(64))
